activity.result = (function() {

    // --- Function declarations at root of function body ---
    function handleError(error, context) {
        var message = "ERROR in " + context + ": " + error;
        workflow.error(message); // Workflow log
        gs.error(message); // System log
        current.comments = (current.comments || "") + "\n" + message; // RITM/Task comments
    }

    function setRESTCommonHeaders(r, authToken) {
        r.setRequestHeader("Authorization", authToken);
        r.setRequestHeader('User-Agent', 'snow');
        r.setRequestHeader("Content-Type", "application/json");
    }

    function setMIDServerIfNeeded(r) {
        if (midServer) {
            r.setMIDServer(midServer);
            r.setEccParameter('skip_sensor', 'true');
        }
    }

    function executeREST(r, step) {
        r.setHttpTimeout(30000);
        var response = r.executeAsync();
        var body = response.getBody();
        workflow.info(step + " - REST response: " + body);
        if (response.haveError()) {
            try {
                var res = JSON.parse(body);
                throw new Error(res.title || body);
            } catch (err) {
                throw new Error(body);
            }
        }
        return JSON.parse(body);
    }

    function attachFileToReqItem(filename, contentType, content) {
        var rec = new GlideRecord('sc_req_item');
        rec.addQuery('sys_id', workflow.scratchpad.req_item_sys_id.toString());
        rec.query();
        if (rec.next()) {
            var attachment = new GlideSysAttachment();
            attachment.write(rec, filename, contentType, content);
            workflow.info("Attached file: " + filename);
        } else {
            workflow.error("Failed to find sc_req_item for attachment: " + filename);
        }
    }

    function updateDeviceRecord(deviceId, resp) {
        var deviceGR = new GlideRecordSecure('x_1784056_sixscape_device');
        deviceGR.addQuery("device_id", deviceId);
        deviceGR.query();
        while (deviceGR.next()) {
            if (resp.expiryDate) {
                var expiryGDT = new GlideDateTime(resp.expiryDate);
                deviceGR.expiry_date = expiryGDT;
            }
            deviceGR.certificate_name = resp.name;
            deviceGR.certificate_status = resp.status;
            deviceGR.certificate_creation_time = resp.createdDate;
            deviceGR.serial_number = resp.serialNumber;
            deviceGR.device_status = "PROVISIONED";
            deviceGR.update();
        }
    }

    function generateComplexPassphrase(length) {
        var upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        var lower = "abcdefghijklmnopqrstuvwxyz";
        var digits = "0123456789";
        var special = "!@#$%^&*()-_=+[]{}|;:,.<>?";
        var allChars = upper + lower + digits + special;

        // Ensure at least one of each type is included
        var pass = [];
        pass.push(upper.charAt(Math.floor(Math.random() * upper.length)));
        pass.push(lower.charAt(Math.floor(Math.random() * lower.length)));
        pass.push(digits.charAt(Math.floor(Math.random() * digits.length)));
        pass.push(special.charAt(Math.floor(Math.random() * special.length)));

        for (var i = pass.length; i < length; i++) {
            pass.push(allChars.charAt(Math.floor(Math.random() * allChars.length)));
        }

        // Shuffle characters for randomness
        pass = pass.sort(function() {
            return 0.5 - Math.random();
        }).join('');
        return pass;
    }

    // --- Main Logic ---
    try {
        // Read once at the top
        var endpoint = gs.getProperty("x_1784056_sixscape.End Point") || "";
        if (endpoint.endsWith("/")) endpoint = endpoint.slice(0, -1);
        var midServer = gs.getProperty("x_1784056_sixscape.Mid Server Name");

        workflow.info("Starting certificate workflow for device: " + current.variables.device.device_name);

        var deviceName = current.variables.device.device_name;
        var deviceSysId = current.variables.device;
        var downloadCertificate = current.variables.download_certificate_only;
        var ownerId = current.variables.profile.profile_group_id.toString();

        // Get Auth Token
        workflow.info("Requesting auth token...");
        var tokenObj = new GetToken();
        var response = tokenObj.TestConnection();
        if (!response || response.length < 2) throw new Error('Invalid response from Token API.');
        var status = response[0],
            responseBody = response[1];
        if (status !== 200) throw new Error("Error while generating the authentication token.");
        var parsed = JSON.parse(responseBody);
        var authToken = "Bearer " + parsed.authToken;
        workflow.info("Auth token acquired.");

        var deviceId, payload, certResp;

        // --- Device Creation ---
        if (deviceName === "Add New Device") {
            payload = {
                "deviceOwnerId": ownerId,
                "deviceName": current.variables.device_name.toString(),
                "preapproved": true,
                "attributes": [{
                        "name": "Serial Number",
                        "value": current.variables.bind_address + ":" + current.variables.bind_port
                    },
                    {
                        "name": "Hostname",
                        "value": current.variables.hostname.toString()
                    },
                    {
                        "name": "Bind Address",
                        "value": current.variables.bind_address.toString()
                    },
                    {
                        "name": "Bind Port",
                        "value": current.variables.bind_port.toString()
                    }
                ]
            };
            workflow.info("Device creation payload: " + JSON.stringify(payload));

            var deviceREST = new sn_ws.RESTMessageV2();
            setMIDServerIfNeeded(deviceREST);
            deviceREST.setHttpMethod("post");
            setRESTCommonHeaders(deviceREST, authToken);
            deviceREST.setEndpoint(endpoint + "/v1/device");
            deviceREST.setRequestBody(JSON.stringify(payload));
            var deviceResp = executeREST(deviceREST, "Device Creation");

            deviceId = deviceResp.deviceId;
            workflow.info("New Device ID: " + deviceId);

            // Insert device record
            var deviceGR = new GlideRecordSecure('x_1784056_sixscape_device');
            deviceGR.initialize();
            deviceGR.device_name = deviceResp.deviceName;
            deviceGR.device_id = deviceResp.deviceId;
            deviceGR.device_owner_id = deviceResp.deviceOwnerId;
            deviceGR.device_status = deviceResp.status;
            deviceGR.profile = current.variables.profile.sys_id;
            deviceGR.insert();
        } else {
            deviceId = current.variables.device.device_id.toString();
        }

        // --- Certificate Request ---
        var isCSRProvided = current.variables.csr.toString() !== "";
        if (!isCSRProvided) {
            var plainPassphrase = generateComplexPassphrase(10); // random 10-char complex pass
            var base64Pass = GlideStringUtil.base64Encode(plainPassphrase);
            workflow.info("Generated Passphrase: " + plainPassphrase);
            workflow.info("Base64 Encoded Passphrase: " + passBase64);
            payload = {
                "entityId": deviceId,
                "profileId": parseInt(current.variables.profile.profile_id, 10),
                "passphrase": base64Pass
            };
			workflow.scratchpad.email_body = "Please find the attached pfx file in the RITM ticket and the passphrase for the file is " + base64Pass;
        } else {
            // Inline normalization of CSR
            var rawCSR = current.variables.csr.toString().replace(/\\r\\n/g, "\r\n");
            payload = {
                "entityId": deviceId,
                "profileId": parseInt(current.variables.profile.profile_id, 10),
                "csr": rawCSR
            };
			workflow.scratchpad.email_body = "Please find the attached cer file in the RITM ticket to download it.";
        }
        workflow.info("Certificate request payload: " + JSON.stringify(payload));

        var certREST = new sn_ws.RESTMessageV2();
        setMIDServerIfNeeded(certREST);
        certREST.setHttpMethod("post");
        setRESTCommonHeaders(certREST, authToken);
        certREST.setEndpoint(endpoint + "/v1/certificate");
        certREST.setRequestBody(JSON.stringify(payload));
        certResp = executeREST(certREST, "Certificate Request");

        // --- Certificate Download and Attachment ---
        if (!isCSRProvided) {
            // Attach PFX
            attachFileToReqItem(
                current.variables.hostname.toString() + ".pfx",
                "application/x-pkcs12",
                certResp.pkcs12
            );
        } else {
            // Download .cer
            var resourceUrl = certResp.resourceUrl;
            var encodedResourceUrl = resourceUrl.split('/').map(encodeURIComponent).join('/');
            workflow.info("Encoded resource URL: " + encodedResourceUrl);

            var certGetREST = new sn_ws.RESTMessageV2();
            setMIDServerIfNeeded(certGetREST);
            certGetREST.setHttpMethod("get");
            setRESTCommonHeaders(certGetREST, authToken);
            certGetREST.setEndpoint(endpoint + "/" + encodedResourceUrl);
            var certGetResp = executeREST(certGetREST, "Certificate Download");

            // Update device record
            updateDeviceRecord(deviceId, certGetResp);

            // Attach CER
            var certContent = certGetResp.content.replace(/\\r/g, "\r").replace(/\\n/g, "\n");
            attachFileToReqItem(
                current.variables.hostname.toString() + ".cer",
                "application/x-x509-ca-cert",
                certContent
            );
        }

        // --- Update Device Record for PFX Case ---
        if (!isCSRProvided) {
            var subfilter = "(name=eq " + deviceId + " $or owner=eq " + deviceId + " $or owner=eq " + ownerId + ")";
            var certListREST = new sn_ws.RESTMessageV2();
            setMIDServerIfNeeded(certListREST);
            certListREST.setHttpMethod("get");
            setRESTCommonHeaders(certListREST, authToken);
            certListREST.setEndpoint(endpoint + "/v1/certificate");
            certListREST.setQueryParameter("$subfilter", subfilter);
            certListREST.setQueryParameter("$sort", "expiryDate desc");
            var certListResp = executeREST(certListREST, "Certificate List");

            if (Array.isArray(certListResp) && certListResp.length > 0) {
                updateDeviceRecord(deviceId, certListResp[0]);
            }
        }

        // --- Download Certificate Only Block (if needed) ---
        if (downloadCertificate == "true") {
            workflow.info("Download certificate section 2");
            // Implement as needed
        }

        workflow.info("Certificate workflow completed successfully.");
        return "true";
    } catch (error) {
        handleError(error, "Certificate Workflow");
        // Mark RITM and Request as incomplete
        current.stage = "closed_incomplete";
        current.state = 4;
        var reqRecord = current.request.getRefRecord();
        if (reqRecord) {
            reqRecord.state = 4;
            reqRecord.request_state = "closed_incomplete";
            reqRecord.update();
        }
        return "false";
    }
})();

