var answer = [];
current.comments = "Your certificate request is pending for approval.";
answer.push(workflow.scratchpad.approval_group_id);

activity.result = (function() {
    try {
        // Get the associated request record
        var requestGR = current.request.getRefRecord();
        requestGR.short_description = 'IDcentral Certificate Request';
        requestGR.update();

        // Store the current request item sys_id in the workflow scratchpad
        workflow.scratchpad.req_item_sys_id = current.sys_id;

        // Get the profile sys_id from variables
        var profileSysId = current.variables.profile;
        workflow.info("Profile Sys ID = " + profileSysId);

        // Query the profile record
        var profileGR = new GlideRecord('x_1784056_sixscape_profile');
        if (profileGR.get(profileSysId)) {
            workflow.scratchpad.approval_enabled = profileGR.getValue('approval_enabled') || 'No';
            workflow.scratchpad.approval_group_id = profileGR.getValue('assignment_group');
        } else {
            workflow.scratchpad.approval_enabled = 'No';
            workflow.scratchpad.approval_group_id = '';
            workflow.info("Profile not found for Sys ID: " + profileSysId);
        }

        workflow.info("Approval Enabled = " + workflow.scratchpad.approval_enabled);
        workflow.info("Approval Group ID = " + workflow.scratchpad.approval_group_id);

        return "true";
    } catch (e) {
